/**
 * @name Path traversal in file read sinks
 * @description Potentially unsafe file path construction / open calls in request handling code
 * @kind problem
 * @problem.severity warning
 * @id py/dj-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node n) {
    n instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node n) {
    n = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;

from DataFlow::Node src, DataFlow::Node sink
where PathTraversalFlow::flow(src, sink)
select sink, "Path traversal: request data from $@ reaches a file system access.", src, "request data"
